/**
 * Recurring transactions: detection, schedule math and upcoming bills.
 */
import { addDays, addMonths, dayOfMonth, daysBetween } from './dates.ts';
import type { Cents, CategoryKind, ISODate, RecurringFrequency, RecurringSeries, TransactionKind } from './types.ts';

export const FREQUENCIES: readonly RecurringFrequency[] = [
  'weekly',
  'biweekly',
  'monthly',
  'quarterly',
  'semiannual',
  'annual',
];

export const FREQUENCY_LABELS: Record<RecurringFrequency, string> = {
  weekly: 'Weekly',
  biweekly: 'Every 2 weeks',
  monthly: 'Monthly',
  quarterly: 'Quarterly',
  semiannual: 'Every 6 months',
  annual: 'Yearly',
};

/** Accepted gap (days) between occurrences for each frequency. */
const BANDS: Record<RecurringFrequency, { min: number; max: number; typical: number }> = {
  weekly: { min: 6, max: 8, typical: 7 },
  biweekly: { min: 13, max: 16, typical: 14 },
  monthly: { min: 26, max: 35, typical: 30.44 },
  quarterly: { min: 84, max: 98, typical: 91.31 },
  semiannual: { min: 172, max: 193, typical: 182.62 },
  annual: { min: 350, max: 380, typical: 365.25 },
};

/** Approximate monthly cost of a recurring amount (for summaries). */
export function monthlyEquivalent(amountCents: Cents, frequency: RecurringFrequency): Cents {
  return Math.round((amountCents * 30.44) / BANDS[frequency].typical);
}

/**
 * The occurrence after `date`. For month-based schedules, `anchorDay` keeps
 * the intended day of month (a bill due on the 31st is due Feb 28, then Mar 31).
 */
export function nextOccurrence(date: ISODate, frequency: RecurringFrequency, anchorDay?: number): ISODate {
  switch (frequency) {
    case 'weekly':
      return addDays(date, 7);
    case 'biweekly':
      return addDays(date, 14);
    case 'monthly':
      return addMonths(date, 1, anchorDay);
    case 'quarterly':
      return addMonths(date, 3, anchorDay);
    case 'semiannual':
      return addMonths(date, 6, anchorDay);
    case 'annual':
      return addMonths(date, 12, anchorDay);
  }
}

/** First occurrence on or after `onOrAfter`, stepping forward from `from`. */
export function rollForward(
  from: ISODate,
  frequency: RecurringFrequency,
  onOrAfter: ISODate,
  anchorDay?: number,
): ISODate {
  let d = from;
  let guard = 0;
  while (d < onOrAfter && guard++ < 1000) d = nextOccurrence(d, frequency, anchorDay);
  return d;
}

export function classifyInterval(days: number): RecurringFrequency | null {
  for (const f of FREQUENCIES) {
    const b = BANDS[f];
    if (days >= b.min && days <= b.max) return f;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Upcoming bills
// ---------------------------------------------------------------------------

export type BillUrgency = 'overdue' | 'soon' | 'upcoming';

export interface UpcomingBill {
  seriesId: string;
  name: string;
  date: ISODate;
  daysUntil: number;
  amountCents: Cents;
  amountMinCents: Cents | null;
  amountMaxCents: Cents | null;
  kind: CategoryKind;
  accountId: string | null;
  categoryId: string | null;
  frequency: RecurringFrequency;
  urgency: BillUrgency;
}

export interface UpcomingOptions {
  horizonDays?: number;
  /** Bills due within this many days are highlighted. */
  soonDays?: number;
  /** Keep showing a missed occurrence for this many days before rolling it forward. */
  overdueGraceDays?: number;
  includeIncome?: boolean;
}

export function upcomingBills(
  series: readonly RecurringSeries[],
  today: ISODate,
  options: UpcomingOptions = {},
): UpcomingBill[] {
  const { horizonDays = 30, soonDays = 7, overdueGraceDays = 5, includeIncome = false } = options;
  const end = addDays(today, horizonDays);
  const graceStart = addDays(today, -overdueGraceDays);
  const out: UpcomingBill[] = [];

  for (const s of series) {
    if (s.status !== 'active') continue;
    if (s.kind === 'income' && !includeIncome) continue;
    const seed = s.nextDate ?? (s.lastDate ? nextOccurrence(s.lastDate, s.frequency) : null);
    if (!seed) continue;
    const anchor = s.frequency === 'weekly' || s.frequency === 'biweekly' ? undefined : dayOfMonth(s.lastDate ?? seed);

    let d = rollForward(seed, s.frequency, graceStart, anchor);
    let guard = 0;
    while (d <= end && guard++ < 60) {
      const daysUntil = daysBetween(today, d);
      out.push({
        seriesId: s.id,
        name: s.name,
        date: d,
        daysUntil,
        amountCents: s.expectedAmountCents,
        amountMinCents: s.amountMinCents,
        amountMaxCents: s.amountMaxCents,
        kind: s.kind,
        accountId: s.accountId,
        categoryId: s.categoryId,
        frequency: s.frequency,
        urgency: daysUntil < 0 ? 'overdue' : daysUntil <= soonDays ? 'soon' : 'upcoming',
      });
      d = nextOccurrence(d, s.frequency, anchor);
    }
  }

  return out.sort((a, b) => a.date.localeCompare(b.date) || a.name.localeCompare(b.name));
}

