export interface RecurringInput {
  id: string;
  date: ISODate;
  amountCents: Cents;
  merchantKey: string;
  name: string;
  accountId: string | null;
  categoryId: string | null;
  kind: TransactionKind;
  pending: boolean;
}

export interface DetectedRecurring {
  merchantKey: string;
  name: string;
  kind: CategoryKind;
  frequency: RecurringFrequency;
  expectedAmountCents: Cents;
  amountMinCents: Cents;
  amountMaxCents: Cents;
  lastDate: ISODate;
  nextDate: ISODate;
  accountId: string | null;
  categoryId: string | null;
  transactionIds: string[];
  /** 0..1 */
  confidence: number;
}

export interface DetectionOptions {
  /** Minimum share of gaps that must fit the frequency. */
  minRegularity?: number;
  /** Minimum share of amounts within tolerance of the typical amount. */
  minAmountConsistency?: number;
  /** Relative amount tolerance (utilities vary month to month). */
  amountTolerance?: number;
}

function median(values: readonly number[]): number {
  const s = [...values].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid]! : (s[mid - 1]! + s[mid]!) / 2;
}

function mostCommon<T>(values: readonly T[]): T | null {
  const counts = new Map<T, number>();
  let best: T | null = null;
  let bestCount = 0;
  for (const v of values) {
    const c = (counts.get(v) ?? 0) + 1;
    counts.set(v, c);
    if (c > bestCount) {
      best = v;
      bestCount = c;
    }
  }
  return best;
}

/**
 * Find merchants that charge (or pay) on a regular schedule with consistent
 * amounts, and that are still active as of `today`.
 */
export function detectRecurring(
  transactions: readonly RecurringInput[],
  today: ISODate,
  options: DetectionOptions = {},
): DetectedRecurring[] {
  const minRegularity = options.minRegularity ?? 0.7;
  const minAmountConsistency = options.minAmountConsistency ?? 0.7;
  const tolerance = options.amountTolerance ?? 0.25;

  const groups = new Map<string, RecurringInput[]>();
  for (const t of transactions) {
    if (t.pending || t.kind === 'transfer' || t.amountCents === 0 || !t.merchantKey) continue;
    const k = `${t.merchantKey}|${t.amountCents > 0 ? 'in' : 'out'}`;
    const list = groups.get(k) ?? [];
    list.push(t);
    groups.set(k, list);
  }

  const results: DetectedRecurring[] = [];
  for (const list of groups.values()) {
    // One occurrence per day; most recent 13 occurrences.
    const byDay = new Map<string, RecurringInput>();
    for (const t of [...list].sort((a, b) => a.date.localeCompare(b.date))) {
      if (!byDay.has(t.date)) byDay.set(t.date, t);
    }
    const occ = [...byDay.values()].slice(-13);
    if (occ.length < 2) continue;

    const gaps = occ.slice(1).map((t, i) => daysBetween(occ[i]!.date, t.date));
    const frequency = classifyInterval(median(gaps));
    if (!frequency) continue;

    const band = BANDS[frequency];
    const longCycle = frequency === 'quarterly' || frequency === 'semiannual' || frequency === 'annual';
    if (occ.length < (longCycle ? 2 : 3)) continue;

    const regularity = gaps.filter((g) => g >= band.min && g <= band.max).length / gaps.length;
    if (regularity < minRegularity) continue;

    const magnitudes = occ.map((t) => Math.abs(t.amountCents));
    const typical = median(magnitudes);
    // Two data points need to agree closely; more points may vary more.
    const tol = occ.length === 2 ? Math.min(tolerance, 0.1) : tolerance;
    const consistent = magnitudes.filter((a) => Math.abs(a - typical) <= Math.max(typical * tol, 100)).length;
    const amountConsistency = consistent / magnitudes.length;
    if (amountConsistency < minAmountConsistency) continue;

    const last = occ[occ.length - 1]!;
    // Stale: we'd have expected at least one more occurrence by now.
    if (daysBetween(last.date, today) > band.max * 1.5 + 5) continue;

    const anchor = longCycle || frequency === 'monthly' ? dayOfMonth(last.date) : undefined;
    const recent = magnitudes.slice(-3);
    results.push({
      merchantKey: last.merchantKey,
      name: last.name,
      kind: last.amountCents > 0 ? 'income' : 'expense',
      frequency,
      expectedAmountCents: Math.round(median(recent)),
      amountMinCents: Math.min(...magnitudes),
      amountMaxCents: Math.max(...magnitudes),
      lastDate: last.date,
      nextDate: nextOccurrence(last.date, frequency, anchor),
      accountId: mostCommon(occ.map((t) => t.accountId)),
      categoryId: [...occ].reverse().find((t) => t.categoryId)?.categoryId ?? null,
      transactionIds: occ.map((t) => t.id),
      confidence: Math.round(regularity * amountConsistency * 100) / 100,
    });
  }

  return results.sort((a, b) => a.name.localeCompare(b.name));
}

export interface RecurringPlan {
  inserts: DetectedRecurring[];
  /** Existing series to refresh. Only schedule fields change for manual/edited series. */
  updates: { id: string; detected: DetectedRecurring; scheduleOnly: boolean }[];
  /** Transactions to link to the series for `merchantKey` (resolved to an id after inserts). */
  links: { transactionId: string; merchantKey: string }[];
}

/**
 * Reconcile detection results with stored series.
 *   * `ignored` series are never resurrected.
 *   * Series the user created or edited (`source = manual`) keep their
 *     amounts/frequency/name; only last/next dates move forward.
 */
export function planRecurringUpdates(
  detected: readonly DetectedRecurring[],
  existing: readonly Pick<RecurringSeries, 'id' | 'merchantKey' | 'status' | 'source' | 'lastDate'>[],
): RecurringPlan {
  const byKey = new Map(existing.filter((s) => s.merchantKey).map((s) => [s.merchantKey!, s]));
  const plan: RecurringPlan = { inserts: [], updates: [], links: [] };
  for (const d of detected) {
    const s = byKey.get(d.merchantKey);
    if (s?.status === 'ignored') continue;
    if (!s) plan.inserts.push(d);
    else if (s.source === 'detected' || !s.lastDate || d.lastDate > s.lastDate) {
      plan.updates.push({ id: s.id, detected: d, scheduleOnly: s.source === 'manual' });
    }
    for (const id of d.transactionIds) plan.links.push({ transactionId: id, merchantKey: d.merchantKey });
  }
  return plan;
}
